from __future__ import annotations

import hashlib
import json
import os
import shlex
import shutil
import subprocess
import sys
from pathlib import Path
from tempfile import TemporaryDirectory
from unittest import mock

from carbon_market import audit, audit_proof

ROOT = Path.cwd()
Q = chr(34)
VALID_TAG = Q + '0' * 64 + Q


def event(key='batch-key'):
    return {'op': 'copy', 'target': 't.history', 'key': key,
            'changed': True, 'error': None, 'stage': None}


def tag(path):
    return Q + hashlib.sha256(Path(path).read_bytes()).hexdigest() + Q


def compact(value):
    return (json.dumps(value, ensure_ascii=False,
                       separators=(',', ':'), allow_nan=False) + '\n').encode()


def expect(error, function):
    try:
        function()
    except error:
        return
    except BaseException as exc:
        raise AssertionError(
            f'expected {error.__name__}, got {type(exc).__name__}: {exc}'
        ) from exc
    raise AssertionError(f'expected {error.__name__}')


def run_cli(*args):
    command = [sys.executable, '-m', 'carbon_market', *map(str, args)]
    return command, subprocess.run(command, cwd=ROOT, capture_output=True,
                                   timeout=30)


def assert_failure(completed, status, code):
    assert completed.returncode == status, (
        completed.returncode, completed.stdout, completed.stderr)
    assert completed.stdout == b'', completed.stdout
    assert completed.stderr == compact({'error': code}), completed.stderr


