    _fsync_dir(os.path.dirname(path) or ".")


def _prepare_dir(ledger_dir: str) -> None:
    # The ledger's companion lock file lives inside the acceptance
    # directory, so the directory itself must exist before the flock is
    # taken. A not-yet-existing directory with a present parent is the
    # first submission and is created here; a missing parent surfaces as
    # FileNotFoundError and an existing non-directory as OSError. mkdir
    # is atomic, so two racing first submissions cannot corrupt one
    # another's directory.
    if os.path.isdir(ledger_dir):
        return
    parent = os.path.dirname(ledger_dir) or "."
    if not os.path.isdir(parent):
        raise FileNotFoundError(parent)
    try:
        os.mkdir(ledger_dir)
    except FileExistsError:
        if not os.path.isdir(ledger_dir):
            raise OSError(f"{ledger_dir!r} is not a directory")
    else:
        _fsync_dir(parent)

